import pandas as pd

def run(inputs: dict) -> dict:
    df = inputs["invoices"].copy()

    amount_bad = df["amount"].isna() | (df["amount"] < 0)
    tax_bad = df["tax"].isna() | (df["tax"] < 0)
    tax_excess = (~df["amount"].isna()) & (~df["tax"].isna()) & (df["tax"] > df["amount"] * 0.5)
    due_null = df["due_date"].isna()
    ref_empty = df["customer_ref"].isna() | (df["customer_ref"].astype(str).str.strip() == "")

    def build_codes(row_idx):
        codes = []
        if amount_bad.iloc[row_idx]:
            codes.append("AMT_BAD")
        if tax_bad.iloc[row_idx]:
            codes.append("TAX_BAD")
        if tax_excess.iloc[row_idx]:
            codes.append("TAX_EXCESS")
        if due_null.iloc[row_idx]:
            codes.append("DUE_NULL")
        if ref_empty.iloc[row_idx]:
            codes.append("REF_EMPTY")
        return "|".join(codes)

    reason_codes = [build_codes(i) for i in range(len(df))]
    df["reason_codes"] = reason_codes

    has_failure = df["reason_codes"] != ""

    rejects = df[has_failure].copy()
    clean = df[~has_failure].copy()
    clean = clean.drop(columns=["reason_codes"])

    return {
        "invoices_clean": clean.reset_index(drop=True),
        "invoices_rejects": rejects.reset_index(drop=True),
    }
